    CREATE OR REPLACE FUNCTION is_pmtct_infant(p_hospital_number TEXT)
RETURNS BOOLEAN
LANGUAGE plpgsql
STABLE
AS $func$
    BEGIN
    IF to_regclass('public.pmtct_infant_information') IS NULL THEN
        RETURN FALSE;
    END IF;

    PERFORM 1
    FROM pmtct_infant_information
    WHERE infant_hospital_number = p_hospital_number;

    RETURN FOUND;

    EXCEPTION WHEN undefined_table THEN
    RETURN FALSE;
    END;
    $func$;
